# 각 도시 이름은 공백, 숫자, 특수문자 등이 없는 영문자로 구성되며, 대소문자 구분을 하지 않는다.
def solution(cacheSize, cities):
    cache_map = {}
    cache_list = ['']*cacheSize
    cache_cnt = 0
    answer = 0

    if cacheSize==0:
        return 5*len(cities)

    for city in cities:
        city = city.lower()
        # 시티가 캐시맵에 있으면
        if city in cache_map:
            # print(f'{city} in here {cache_map[city]}')
            answer += 1
            idx = cache_map[city]
            # 시티 이후의 인덱스를 앞 인덱스로 시프트
            for i in range(idx+1, cache_cnt): 
                tmp_city = cache_list[i]
                cache_map[tmp_city] -= 1
                cache_list[i-1] = tmp_city
            # 시티를 맨 뒤에 삽입
            cache_map[city] = cache_cnt-1
            cache_list[cache_cnt-1] = city
        # 시티가 캐시맵에 없으면
        else:
            answer += 5
            if cache_cnt == cacheSize:
                # print('cache full')
                # 인덱스1 제거, 2부터 -1
                for i, v in enumerate(cache_list):
                    if i==0:
                        del cache_map[v]
                    else:
                        cache_map[v] -= 1
                        cache_list[i-1] = v
                # 새 도시 넣기
                cache_map[city] = cacheSize-1
                cache_list[-1] = city
            else:
                # print('cache not full')
                cache_map[city] = cache_cnt
                cache_list[cache_cnt] = city
                cache_cnt += 1
        # print()
        # print(city)
        # print(cache_map)
        # print(cache_list)

    return answer

print()
print(solution(3, ["Jeju", "Pangyo", "Seoul", "NewYork", "LA", "Jeju", "Pangyo", "Seoul", "NewYork", "LA"]))
print(50)

print()
print(solution(3, ["Jeju", "Pangyo", "Seoul", "Jeju", "Pangyo", "Seoul", "Jeju", "Pangyo", "Seoul"]))
print(21)

